malpipe/configs/cobaltstrike.py:
"""Configuracion de un beacon de Cobalt Strike.

El beacon guarda su configuracion como una tabla TLV (id, tipo, longitud, valor;
enteros en big endian) cifrada con un XOR de un byte: 0x69 en la version 3 y
0x2e en la 4. Se reconoce por el principio, que siempre es el ajuste 1
(BeaconType, tipo short, longitud 2): 00 01 00 01 00 02.

Es el formato que leen las herramientas publicas (1768.py de Didier Stevens,
CobaltStrikeParser de SentinelOne). Sale en claro en un beacon sin cifrar o en
un volcado de memoria; en un stager o en un beacon con la configuracion
ofuscada por un "sleep mask" no se encuentra.
"""
from __future__ import annotations

import struct

from ..models import FamilyConfig

CABECERA = b"\x00\x01\x00\x01\x00\x02"
CLAVES_XOR = (0x2E, 0x69, 0x00)
TAMANO_MAXIMO = 6144          # 4096 en la version 3, 6144 en la 4

# Solo los ajustes cuyo significado esta bien documentado; el resto sale como
# "ajuste_<n>" para que el analista lo vea sin inventarle un nombre.
AJUSTES = {
    1: "BeaconType", 2: "Port", 3: "SleepTime", 4: "MaxGetSize", 5: "Jitter", 6: "MaxDNS",
    7: "PublicKey", 8: "C2Server", 9: "UserAgent", 10: "HttpPostUri", 15: "PipeName",
    19: "DNS_Idle", 20: "DNS_Sleep", 26: "HttpGet_Verb", 27: "HttpPost_Verb", 28: "HttpPostChunk",
    29: "Spawnto_x86", 30: "Spawnto_x64", 31: "CryptoScheme", 37: "Watermark", 40: "KillDate",
}
TIPOS_BEACON = {0: "HTTP", 1: "Hybrid HTTP DNS", 2: "SMB", 4: "TCP", 8: "HTTPS", 16: "Bind TCP"}
SIN_MOSTRAR = {7, 11, 12, 13}  # clave publica y bloques de Malleable C2: binarios largos


def _xor(datos: bytes, clave: int) -> bytes:
    return datos if clave == 0 else bytes(b ^ clave for b in datos)


def _tlv(bloque: bytes) -> dict[int, object]:
    ajustes: dict[int, object] = {}
    pos = 0
    while pos + 6 <= len(bloque):
        ident, tipo, largo = struct.unpack_from(">HHH", bloque, pos)
        pos += 6
        if ident == 0:
            break
        if tipo not in (1, 2, 3) or pos + largo > len(bloque) or ident > 128:
            break                                    # ya no es la tabla
        valor = bloque[pos:pos + largo]
        pos += largo
        if tipo == 1 and largo >= 2:
            ajustes[ident] = struct.unpack(">H", valor[:2])[0]
        elif tipo == 2 and largo >= 4:
            ajustes[ident] = struct.unpack(">I", valor[:4])[0]
        else:
            ajustes[ident] = valor
    return ajustes


def _texto(v: object) -> str:
    if isinstance(v, bytes):
        return v.split(b"\x00", 1)[0].decode("latin-1", "replace")
    return str(v)


def extraer(data: bytes) -> FamilyConfig | None:
    for clave in CLAVES_XOR:
        marca = _xor(CABECERA, clave)
        inicio = data.find(marca)
        while inicio != -1:
            ajustes = _tlv(_xor(data[inicio:inicio + TAMANO_MAXIMO], clave))
            if 1 in ajustes and 2 in ajustes and (8 in ajustes or ajustes.get(1) in (2, 4, 16)):
                return _configuracion(ajustes, clave)
            inicio = data.find(marca, inicio + 1)
    return None


def _configuracion(ajustes: dict[int, object], clave: int) -> FamilyConfig:
    tipo = ajustes.get(1)
    puerto = ajustes.get(2)
    valores: dict[str, object] = {"xor": f"0x{clave:02x}",
                                  "version": {0x2E: "4.x", 0x69: "3.x"}.get(clave, "sin cifrar")}
    for ident, v in sorted(ajustes.items()):
        if ident in SIN_MOSTRAR:
            continue
        nombre = AJUSTES.get(ident, f"ajuste_{ident}")
        valores[nombre] = _texto(v)
    valores["BeaconType"] = TIPOS_BEACON.get(tipo, str(tipo))

    c2: list[str] = []
    servidores = _texto(ajustes.get(8, b"")).split(",")
    esquema = "https" if tipo == 8 else "http"
    uris = servidores[1::2] + [""] * len(servidores)
    for host, uri in zip(servidores[0::2], uris[:len(servidores[0::2])], strict=True):
        host = host.strip()
        if host:
            c2.append(f"{esquema}://{host}:{puerto}{uri.strip()}" if tipo in (0, 1, 8) else f"{host}:{puerto}")
    return FamilyConfig(family="Cobalt Strike", extractor="cobaltstrike", c2=c2, values=valores,
                        confidence="alta")

malpipe/configs/remcos.py:
"""Configuracion de Remcos RAT.

Remcos guarda su configuracion en un recurso RT_RCDATA llamado SETTINGS: el
primer byte es la longitud de la clave, despues la clave y despues la
configuracion cifrada con RC4. En claro, los campos van separados por
"|\\x1e\\x1e\\x1f|" y el primero es la lista de C2 (host:puerto:tls, separados por
\\x1e). Es el formato que describen los analisis publicos de Remcos 3.x y 4.x.
"""
from __future__ import annotations

import re

from ..models import FamilyConfig

try:
    import pefile  # type: ignore
except ImportError:  # pragma: no cover - pefile es dependencia del nucleo
    pefile = None

SEPARADORES = (b"|\x1e\x1e\x1f|", b"\x1e\x1e\x1f")
MUTEX = re.compile(r"^(Rmc-[A-Z0-9]{6}|Remcos_Mutex_Inj)$")


def rc4(clave: bytes, datos: bytes) -> bytes:
    s = list(range(256))
    j = 0
    for i in range(256):
        j = (j + s[i] + clave[i % len(clave)]) & 0xFF
        s[i], s[j] = s[j], s[i]
    i = j = 0
    salida = bytearray()
    for b in datos:
        i = (i + 1) & 0xFF
        j = (j + s[i]) & 0xFF
        s[i], s[j] = s[j], s[i]
        salida.append(b ^ s[(s[i] + s[j]) & 0xFF])
    return bytes(salida)


def recurso_settings(data: bytes) -> bytes | None:
    if pefile is None or data[:2] != b"MZ":
        return None
    try:
        pe = pefile.PE(data=data, fast_load=True)
        pe.parse_data_directories(directories=[pefile.DIRECTORY_ENTRY["IMAGE_DIRECTORY_ENTRY_RESOURCE"]])
    except pefile.PEFormatError:
        return None
    raiz = getattr(pe, "DIRECTORY_ENTRY_RESOURCE", None)
    for tipo in raiz.entries if raiz else []:
        if tipo.id != pefile.RESOURCE_TYPE["RT_RCDATA"] or not hasattr(tipo, "directory"):
            continue
        for nombre in tipo.directory.entries:
            if not nombre.name or str(nombre.name).upper() != "SETTINGS" or not hasattr(nombre, "directory"):
                continue
            for idioma in nombre.directory.entries:
                d = idioma.data.struct
                return pe.get_data(d.OffsetToData, d.Size)
    return None


def descifrar(blob: bytes) -> bytes | None:
    if len(blob) < 3:
        return None
    largo = blob[0]
    if not 1 <= largo < len(blob) - 1:
        return None
    return rc4(blob[1:1 + largo], blob[1 + largo:])


def extraer(data: bytes) -> FamilyConfig | None:
    blob = recurso_settings(data)
    if not blob:
        return None
    claro = descifrar(blob)
    if not claro:
        return None
    sep = next((s for s in SEPARADORES if s in claro), None)
    if sep is None:
        return None
    campos = [c.decode("latin-1", "replace").strip("\x00") for c in claro.split(sep)]
    c2 = []
    for entrada in re.split(r"[\x1e|]", campos[0]):
        partes = entrada.split(":")
        if len(partes) >= 2 and partes[0] and partes[1].isdigit():
            c2.append(f"{partes[0]}:{partes[1]}")
    if not c2:
        return None
    valores: dict[str, object] = {"nombre_asignado": campos[1] if len(campos) > 1 else "",
                                  "campos": len(campos)}
    tls = [e.split(":")[2] for e in re.split(r"[\x1e|]", campos[0]) if e.count(":") >= 2]
    if tls:
        valores["tls"] = tls
    mutex = next((c for c in campos if MUTEX.match(c)), "")
    if mutex:
        valores["mutex"] = mutex
    return FamilyConfig(family="Remcos", extractor="remcos", c2=c2, values=valores, confidence="alta")

malpipe/dynamic/cape.py:
"""Analisis dinamico en una instancia propia de CAPEv2 (host aislado).

A diferencia de tria.ge, la muestra no sale de tu red: se detona en tu CAPE,
que ademas extrae la configuracion de muchas familias de su volcado de memoria
(lo que el analisis estatico no ve si la muestra esta empaquetada).

API v2 de CAPE (web/apiv2/ en el repositorio de CAPEv2):
  POST {CAPE_URL}/apiv2/tasks/create/file/          -> data.task_ids
  GET  {CAPE_URL}/apiv2/tasks/status/<id>/          -> data: pending | running | completed | reported | failed_*
  GET  {CAPE_URL}/apiv2/tasks/get/report/<id>/json/ -> informe completo
Con autenticacion por token (api.conf), cabecera "Authorization: Token <token>".

Configuracion: CAPE_URL, CAPE_TOKEN, CAPE_OPCIONES (p. ej. "route=none"),
CAPE_VERIFICAR_TLS (1 por defecto). Como montar el host: docs/CAPE.md.

Probado con respuestas simuladas que siguen esa API (tests/test_cape.py), no
contra una instancia real.
"""
from __future__ import annotations

import time

from ..config import config
from ..models import DynamicResult, FamilyConfig

try:
    import requests  # type: ignore
except ImportError:  # pragma: no cover
    requests = None

FALLIDOS = ("failed_analysis", "failed_processing", "failed_reporting", "banned")


def _cab() -> dict[str, str]:
    return {"Authorization": f"Token {config.cape_token}"} if config.cape_token else {}


def _api(ruta: str) -> str:
    return f"{config.cape_url.rstrip('/')}/apiv2/{ruta.lstrip('/')}"


def _pedir(metodo: str, ruta: str, **kw):
    r = requests.request(metodo, _api(ruta), headers=_cab(), timeout=kw.pop("timeout", 60),
                         verify=config.cape_verify_tls, **kw)
    r.raise_for_status()
    datos = r.json()
    if isinstance(datos, dict) and datos.get("error"):
        raise RuntimeError(datos.get("error_value") or "CAPE devolvio un error")
    return datos


def _enviar(nombre: str, datos: bytes) -> int:
    form = {"options": config.cape_options} if config.cape_options else {}
    r = _pedir("POST", "tasks/create/file/", files={"file": (nombre, datos)}, data=form)
    ids = (r.get("data") or {}).get("task_ids") or []
    if not ids:
        raise RuntimeError("CAPE no devolvio ninguna tarea")
    return int(ids[0])


def _esperar(tarea: int) -> str:
    fin = time.time() + config.dynamic_timeout
    estado = ""
    while time.time() < fin:
        estado = str(_pedir("GET", f"tasks/status/{tarea}/", timeout=30).get("data", ""))
        if estado == "reported" or estado in FALLIDOS:
            return estado
        time.sleep(config.cape_intervalo)
    return estado or "sin respuesta"


def _lista(valor) -> list:
    return valor if isinstance(valor, list) else []


def interpretar(informe: dict, res: DynamicResult) -> list[FamilyConfig]:
    """Rellena res con el informe de CAPE y devuelve las configuraciones extraidas."""
    res.analyzed = True
    malscore = informe.get("malscore")
    res.score = float(malscore) if isinstance(malscore, (int, float)) else None

    familias = []
    det = informe.get("detections")
    for d in det if isinstance(det, list) else [det] if det else []:
        nombre = d.get("family") if isinstance(d, dict) else d
        if nombre and nombre not in familias:
            familias.append(str(nombre))
    res.family = ", ".join(familias)

    ttps = set()
    for sig in _lista(informe.get("signatures")):
        if isinstance(sig, dict) and sig.get("name"):
            res.signatures.append(str(sig.get("description") or sig["name"]))
            ttps.update(str(t) for t in _lista(sig.get("ttp")) if str(t).startswith("T"))
    for t in _lista(informe.get("ttps")):
        if isinstance(t, dict):
            ttps.update(str(x) for x in _lista(t.get("ttps")) if str(x).startswith("T"))
        elif str(t).startswith("T"):
            ttps.add(str(t))
    res.signatures = sorted(set(res.signatures))
    res.ttps = sorted(ttps)

    red = informe.get("network") or {}
    res.hosts = sorted({(h.get("ip") if isinstance(h, dict) else h) for h in _lista(red.get("hosts"))} - {None, ""})
    res.domains = sorted({(d.get("domain") if isinstance(d, dict) else d)
                          for d in _lista(red.get("domains"))} - {None, ""})
    res.urls = sorted({h.get("uri") for h in _lista(red.get("http")) if isinstance(h, dict) and h.get("uri")})

    configs = []
    for entrada in _lista((informe.get("CAPE") or {}).get("configs")):
        if not isinstance(entrada, dict):
            continue
        for familia, valores in entrada.items():
            if not isinstance(valores, dict):
                continue
            c2 = []
            for clave, v in valores.items():
                if any(k in clave.lower() for k in ("c2", "address", "url", "domain", "host")):
                    c2.extend(str(x) for x in (v if isinstance(v, list) else [v]) if x)
            configs.append(FamilyConfig(family=familia, extractor="cape", c2=sorted(set(c2)),
                                        values={k: v for k, v in valores.items()}, confidence="alta",
                                        source="dynamic"))
    return configs


def run_cape(nombre: str, datos: bytes) -> tuple[DynamicResult, list[FamilyConfig]]:
    res = DynamicResult(engine="CAPEv2")
    if not config.cape_url:
        res.error = "sin CAPE_URL"
        return res, []
    if requests is None:
        res.error = "falta el paquete 'requests'"
        return res, []
    try:
        tarea = _enviar(nombre, datos)
        res.sandbox_url = f"{config.cape_url.rstrip('/')}/analysis/{tarea}/"
        estado = _esperar(tarea)
        if estado != "reported":
            res.error = f"la tarea {tarea} termino en '{estado}'"
            return res, []
        informe = _pedir("GET", f"tasks/get/report/{tarea}/json/", timeout=120)
        return res, interpretar(informe, res)
    except Exception as exc:  # noqa: BLE001 - el pipeline no se cae por el sandbox
        res.error = f"{type(exc).__name__}: {exc}"
        return res, []

malpipe/dynamic/triage.py:
"""Análisis dinámico a través del sandbox gestionado tria.ge (Hatching Triage).

La muestra se detona en la infraestructura del sandbox, NO en la máquina local.
Requiere TRIAGE_API_KEY. Si no hay clave, el pipeline omite esta fase.

Nota: el esquema exacto de la API de tria.ge puede cambiar. El parseo es
defensivo (todo con .get). Verifica los endpoints contra la documentación
vigente en https://tria.ge/docs si algo deja de encajar.
"""
from __future__ import annotations

import time

from ..config import config
from ..models import DynamicResult

try:
    import requests  # type: ignore
    _HAS_REQUESTS = True
except ImportError:
    _HAS_REQUESTS = False


def _headers() -> dict[str, str]:
    return {"Authorization": f"Bearer {config.triage_api_key}"}


def _submit(data: bytes, filename: str) -> str:
    url = f"{config.triage_base_url}/samples"
    files = {"file": (filename, data)}
    payload = {"_json": '{"kind":"file","interactive":false}'}
    r = requests.post(url, headers=_headers(), data=payload, files=files, timeout=60)
    r.raise_for_status()
    return r.json().get("id", "")


def _wait_for_report(sample_id: str) -> bool:
    url = f"{config.triage_base_url}/samples/{sample_id}"
    deadline = time.time() + config.dynamic_timeout
    while time.time() < deadline:
        r = requests.get(url, headers=_headers(), timeout=30)
        r.raise_for_status()
        status = r.json().get("status", "")
        if status == "reported":
            return True
        if status in ("failed", "canceled"):
            return False
        time.sleep(10)
    return False


def _overview(sample_id: str) -> dict:
    url = f"{config.triage_base_url}/samples/{sample_id}/overview.json"
    r = requests.get(url, headers=_headers(), timeout=30)
    r.raise_for_status()
    return r.json()


def run_triage(filename: str, data: bytes) -> DynamicResult:
    res = DynamicResult(engine="tria.ge")
    if not config.triage_api_key:
        res.error = "sin TRIAGE_API_KEY"
        return res
    if not _HAS_REQUESTS:
        res.error = "falta el paquete 'requests'"
        return res

    try:
        sample_id = _submit(data, filename)
        if not sample_id:
            res.error = "el sandbox no devolvió id de muestra"
            return res
        res.sandbox_url = f"https://tria.ge/{sample_id}"

        if not _wait_for_report(sample_id):
            res.error = "el informe no estuvo listo dentro del timeout"
            return res

        overview = _overview(sample_id)
        res.analyzed = True

        analysis = overview.get("analysis", {})
        res.score = analysis.get("score")
        family = analysis.get("family") or (overview.get("targets") or [{}])[0].get("family")
        if isinstance(family, list):
            family = ", ".join(family)
        res.family = family or ""

        for sig in overview.get("signatures", []):
            name = sig.get("name") or sig.get("desc") or ""
            if name:
                res.signatures.append(name)

        res.signatures = sorted(set(res.signatures))
    except Exception as exc:  # noqa: BLE001 — el pipeline no debe caerse por el sandbox
        res.error = f"{type(exc).__name__}: {exc}"
    return res

malpipe/enrich/cti.py:
"""Cruce con News CTI (cti.carlosvillalbalagos.com).

Busca los indicadores de la muestra (sus hashes, las IP, dominios y URL de sus
cadenas, los C2 de su configuracion y lo que vio el sandbox en la red) en el
feed publico de News CTI, el mismo data/iocs_latest.json que consumen
DetectionLab y ResponseLab. Un hash que ya esta en el feed es malware conocido;
una IP o un dominio en el feed son infraestructura que alguien ya ha visto
atacar.

El feed se descarga una vez por ejecucion (o se lee de un fichero con
--cti-fichero). En el portal web lo descarga el navegador y se lo pasa al mismo
codigo.
"""
from __future__ import annotations

import ipaddress
import json
import os
import urllib.request
from urllib.parse import urlsplit

from ..models import CtiCheck, CtiMatch, DynamicResult, FamilyConfig, StaticResult

FEED_POR_DEFECTO = "https://raw.githubusercontent.com/BlueShield-Ch4rl13/ScriptNewsCTI/main/data/iocs_latest.json"
TIPOS_HASH = {"filehash-md5": "md5", "filehash-sha1": "sha1", "filehash-sha256": "sha256"}


def cargar_feed(fuente: str = "", timeout: int = 20) -> dict:
    """fuente: URL o ruta de un iocs_latest.json. Vacia: MALPIPE_CTI_URL o el feed publico."""
    fuente = fuente or os.getenv("MALPIPE_CTI_URL", FEED_POR_DEFECTO)
    if os.path.exists(fuente):
        with open(fuente, encoding="utf-8") as f:
            datos = json.load(f)
    else:
        req = urllib.request.Request(fuente, headers={"User-Agent": "malpipe"})
        with urllib.request.urlopen(req, timeout=timeout) as r:   # noqa: S310 - URL de configuracion
            datos = json.load(r)
    datos.setdefault("_fuente", fuente)
    return datos


def _norm(tipo: str, valor: str) -> str:
    valor = valor.strip()
    if tipo == "ip:port":
        return valor.rsplit(":", 1)[0]
    if tipo == "url":
        return valor.rstrip("/")
    return valor.lower()


def _clave_tipo(tipo: str) -> str:
    if tipo in TIPOS_HASH:
        return "hash"
    if tipo in ("ipv4", "ip:port", "ip"):
        return "ip"
    if tipo in ("domain", "hostname"):
        return "dominio"
    return tipo


def indexar(feed: dict) -> dict[tuple[str, str], dict]:
    indice: dict[tuple[str, str], dict] = {}
    for ioc in feed.get("iocs") or []:
        tipo = str(ioc.get("type", ""))
        for v in [ioc.get("value", ""), *(ioc.get("variants") or [])]:
            if v:
                indice.setdefault((_clave_tipo(tipo), _norm(tipo, str(v))), ioc)
    return indice


def _es_ip(v: str) -> bool:
    try:
        ipaddress.ip_address(v)
        return True
    except ValueError:
        return False


def _host_de(c2: str) -> str:
    if "://" in c2:
        return urlsplit(c2).hostname or ""
    return c2.rsplit(":", 1)[0] if c2.count(":") == 1 else c2


def candidatos(static: StaticResult, dynamic: DynamicResult, configs: list[FamilyConfig]) -> list[tuple[str, str]]:
    """(clave de tipo, valor normalizado) de todo lo que la muestra deja ver."""
    vistos: list[tuple[str, str]] = []

    def anadir(clave: str, valor: str) -> None:
        if valor and (clave, valor) not in vistos:
            vistos.append((clave, valor))

    h = static.hashes
    for valor in (h.sha256, h.sha1, h.md5):
        anadir("hash", valor.lower())
    for ip in [*static.indicators.ips, *dynamic.hosts]:
        anadir("ip", ip)
    for d in [*static.indicators.domains, *dynamic.domains]:
        anadir("dominio", d.lower())
    urls = [*static.indicators.urls, *dynamic.urls, *(c for cfg in configs for c in cfg.c2 if "://" in c)]
    for u in urls:
        anadir("url", u.rstrip("/"))
        host = (urlsplit(u).hostname or "").lower()
        anadir("ip" if _es_ip(host) else "dominio", host)
    for cfg in configs:
        for c in cfg.c2:
            host = _host_de(c).lower()
            anadir("ip" if _es_ip(host) else "dominio", host)
    return vistos


def cruzar(static: StaticResult, dynamic: DynamicResult, configs: list[FamilyConfig], feed: dict) -> CtiCheck:
    indice = indexar(feed)
    chk = CtiCheck(checked=True, source=str(feed.get("_fuente", "")), generated=str(feed.get("generated_utc", "")),
                   indicators=len(feed.get("iocs") or []))
    for clave, valor in candidatos(static, dynamic, configs):
        ioc = indice.get((clave, valor))
        if not ioc:
            continue
        chk.matches.append(CtiMatch(
            value=str(ioc.get("value", "")), type=str(ioc.get("type", "")), matched=valor,
            threat=str(ioc.get("threat", "")), level=str(ioc.get("level", "")),
            score=ioc.get("score"), sources=list(ioc.get("sources") or []),
            reference=str(ioc.get("reference", "")), first_seen=str(ioc.get("first_seen", ""))))
    return chk

malpipe/export/misp.py:
"""Informe -> evento MISP (formato JSON de importacion de MISP).

Un evento por muestra con sus atributos (hashes, nombre, IP, dominios, URL,
correos y los C2 de la configuracion), etiquetado TLP:AMBER y con las tecnicas
ATT&CK como etiquetas de la galaxia mitre-attack-pattern. Se importa en MISP
desde Events > Import from... > MISP JSON, o con PyMISP (add_event).

Los atributos de red y los hashes van con to_ids solo si el veredicto es
malicioso: un IOC de una muestra limpia no debe acabar en las reglas de
deteccion de nadie.
"""
from __future__ import annotations

import ipaddress
import uuid

from ..models import Report

ESPACIO = uuid.UUID("6b1c1bd6-5a51-4f5e-9c6f-6d6d2d3a6a10")    # propio de malpipe
NIVEL = {"malicioso": "1", "sospechoso": "2", "limpio": "3", "desconocido": "4"}


def _uuid(*partes: object) -> str:
    return str(uuid.uuid5(ESPACIO, "|".join(str(p) for p in partes)))


def _es_ip(v: str) -> bool:
    try:
        ipaddress.ip_address(v)
        return True
    except ValueError:
        return False


def a_misp(report: Report) -> dict:
    st = report.static
    ids = report.verdict == "malicioso"
    atributos: list[dict] = []

    def attr(tipo: str, categoria: str, valor: str, to_ids: bool, comentario: str = "") -> None:
        if not valor:
            return
        if any(a["type"] == tipo and a["value"] == valor for a in atributos):
            return
        atributos.append({"uuid": _uuid(st.hashes.sha256, tipo, valor), "type": tipo, "category": categoria,
                          "value": valor, "to_ids": to_ids, "comment": comentario})

    attr("filename", "Payload delivery", st.filename, False)
    attr("sha256", "Payload delivery", st.hashes.sha256, ids)
    attr("sha1", "Payload delivery", st.hashes.sha1, ids)
    attr("md5", "Payload delivery", st.hashes.md5, ids)
    attr("imphash", "Payload delivery", st.hashes.imphash, False)
    attr("ssdeep", "Payload delivery", st.hashes.ssdeep, False)
    for ip in st.indicators.ips:
        attr("ip-dst", "Network activity", ip, ids, "en las cadenas de la muestra")
    for d in st.indicators.domains:
        attr("domain", "Network activity", d, ids, "en las cadenas de la muestra")
    for u in st.indicators.urls:
        attr("url", "Network activity", u, ids, "en las cadenas de la muestra")
    for e in st.indicators.emails:
        attr("email-src", "Payload delivery", e, False, "en las cadenas de la muestra")
    for cfg in report.configs:
        for c2 in cfg.c2:
            comentario = f"C2 de {cfg.family} (configuracion extraida, confianza {cfg.confidence})"
            if "://" in c2:
                attr("url", "Network activity", c2, True, comentario)
            elif c2.count(":") == 1:
                host, puerto = c2.split(":")
                attr("ip-dst|port" if _es_ip(host) else "hostname|port", "Network activity",
                     f"{host}|{puerto}", True, comentario)
            else:
                attr("ip-dst" if _es_ip(c2) else "hostname", "Network activity", c2, True, comentario)
    for y in st.yara:
        attr("comment", "Other", f"YARA: {y.rule}", False)

    etiquetas = [{"name": "tlp:amber"}, {"name": f'malpipe:veredicto="{report.verdict}"'}]
    for t in report.attack:
        etiquetas.append({"name": f'misp-galaxy:mitre-attack-pattern="{t.name} - {t.id}"'})
    familias = sorted({c.family for c in report.configs}
                      | ({report.dynamic.family} if report.dynamic.family else set()))

    return {"Event": {
        "uuid": _uuid(st.hashes.sha256, report.generated_at),
        "info": f"malpipe: {st.filename} - {report.verdict} ({report.score}/100)"
                + (f" - {', '.join(familias)}" if familias else ""),
        "date": report.generated_at[:10],
        "threat_level_id": NIVEL.get(report.verdict, "4"),
        "analysis": "2",
        "distribution": "0",
        "Tag": etiquetas,
        "Attribute": atributos,
    }}

